style.css:
/* Sakura Dream — Facebook */
:root {
  /* Có thể thay đổi bảng màu tại đây */
  --my-bg: #fff0f4;
  --my-card: #fffafd;
  --my-accent: #e89ab5;
  --my-accent-light: #f8d5e1;
  --my-text: #634653;
  --my-muted: #ad8998;
  --my-border: #f3dce5;
}

/* nền tổng thể */
html,
body {
  background-color: var(--my-bg) !important;
  color: var(--my-text) !important;
}

/* màu chữ */
body {
  --primary-text: var(--my-text) !important;
  --secondary-text: var(--my-muted) !important;
}

/* liên kết */
a {
  color: #d77f9e !important;
}

/* nút bấm */
button,
[role="button"] {
  border-radius: 14px !important;
}

/* hiệu ứng chọn văn bản */
::selection {
  background: #f5c4d6 !important;
  color: #634653 !important;
}

/* thanh cuộn */
::-webkit-scrollbar {
  width: 8px !important;
}

::-webkit-scrollbar-thumb {
  background: #e9b2c7 !important;
  border-radius: 20px !important;
}

::-webkit-scrollbar-track {
  background: #fff0f4 !important;
}
